style.css:
@-moz-document domain("youtube.com") {
:root {
    --bg: #F5F0E6;
    --card: #FBF7F0;
    --text: #4A3F35;
    --text2: #7A6B5D;
    --border: #E8DFD0;
    --chip: #EFE8DC;
    --clay: #A6534F;
  }

  /* Fondo general */
  html, body, ytd-app, #content, ytd-page-manager, #page-manager,
  ytd-browse, #columns, #primary, #secondary, ytd-watch-flexy {
    background-color: var(--bg) !important;
    color: var(--text) !important;
  }

  /* Header */
  ytd-masthead, #masthead-container, #background {
    background-color: var(--bg) !important;
    border-bottom: 1px solid var(--border) !important;
    box-shadow: none !important;
  }

  /* Sidebar */
  #guide-content, ytd-guide-renderer {
    background-color: var(--bg) !important;
  }

  /* Chips */
  #chips-wrapper, ytd-feed-filter-chip-bar-renderer {
    background-color: var(--bg) !important;
  }

  yt-chip-cloud-chip-renderer {
    background-color: var(--chip) !important;
    border-radius: 999px !important;
  }

  yt-chip-cloud-chip-renderer[selected] {
    background-color: #E5D9C8 !important;
  }

  yt-chip-cloud-chip-renderer #text {
    color: var(--text) !important;
  }

  /* Cards */
  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-compact-video-renderer {
    background-color: var(--card) !important;
    border-radius: 14px !important;
    border: none !important;
    overflow: hidden !important;
  }

  /* Miniaturas */
  ytd-thumbnail, #thumbnail {
    border-radius: 12px !important;
    overflow: hidden !important;
  }

  ytd-thumbnail img, #thumbnail img {
    border-radius: 12px !important;
    filter: brightness(1.04) saturate(0.90) sepia(0.07) !important;
  }

  /* Textos */
  #video-title {
    color: var(--text) !important;
    font-family: Georgia, "Times New Roman", serif !important;
  }

  #metadata-line, #published-time-text {
    color: var(--text2) !important;
  }

  /* ========== LOGO (NO TOCAR - se queda como está) ========== */
  #logo-icon {
    filter: 
      saturate(0.85) 
      hue-rotate(-18deg) 
      brightness(0.92) 
      contrast(1.05) !important;
  }

  /* ========== BARRA DE REPRODUCCIÓN ========== */
  .ytp-play-progress {
    background: linear-gradient(90deg, #A6534F, #C47A6A) !important;
  }

  .ytp-swatch-background-color {
    background-color: var(--clay) !important;
  }

  .ytp-progress-list {
    background-color: rgba(166, 83, 79, 0.18) !important;
  }

  /* Bolita - intento más fuerte de centrarla */
  .ytp-scrubber-button {
    width: 12px !important;
    height: 12px !important;
    background-color: var(--clay) !important;
    border: 2px solid #F5F0E6 !important;
    border-radius: 50% !important;
    box-shadow: 0 0 0 1.5px rgba(166, 83, 79, 0.3) !important;
    position: relative !important;
    top: 0 !important;
    margin-top: -6px !important; /* ajusta verticalmente */
    transform: none !important;
  }

  .ytp-scrubber-button:hover {
    transform: scale(1.15) !important;
  }

  /* ========== PLAYLIST - ataque más fuerte al corte ========== */
  ytd-playlist-panel-renderer {
    background-color: #FFFFFF !important;
    border: none !important;
    border-radius: 14px !important;
    overflow: hidden !important;
    box-shadow: 0 3px 14px rgba(90, 70, 50, 0.07) !important;
  }

  ytd-playlist-panel-renderer *,
  ytd-playlist-panel-renderer #container,
  ytd-playlist-panel-renderer #header,
  ytd-playlist-panel-renderer #items,
  ytd-playlist-panel-renderer #playlist-actions,
  ytd-playlist-panel-video-renderer,
  #content.ytd-playlist-panel-video-renderer {
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
  }

  ytd-playlist-panel-renderer #container {
    border-radius: 14px !important;
    overflow: hidden !important;
  }

  ytd-playlist-panel-video-renderer:hover {
    background-color: #F7F2E9 !important;
  }
}
